def norm_sqrt17(a, b):
    return abs(a*a - _sage_const_17 *b*b)

def find_sqrt17_norm(N, limit=_sage_const_300 ):
    for b in range(_sage_const_0 , limit):
        # a^2 = N + 17*b^2
        a_sq = N + _sage_const_17 *b*b
        a = int(a_sq**_sage_const_0p5  + _sage_const_0p5 )
        if a*a == a_sq:
            return (a, b)
        # 17*b^2 - N = a^2
        a_sq2 = _sage_const_17 *b*b - N
        if a_sq2 >= _sage_const_0 :
            a2 = int(a_sq2**_sage_const_0p5  + _sage_const_0p5 )
            if a2*a2 == a_sq2:
                return (a2, b)
    return None

